## Prints a formatted player identity card.
func print_identity_card(hero_name, hero_rank, ready_message):
    if hero_name == "":
        hero_name = "Unknown"
    if hero_rank == "":
        hero_rank = "Rookie"
    print("Hero: " + hero_name + " | Rank: " + hero_rank + " | Status: " + ready_message)

print_identity_card(hero_name, hero_rank, ready_message)
